class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int n = nums.length;
        // Each slot can hold up to 2 numbers, so total capacity = 2 * numSlots
        // We represent the state of slots using base-3 digits (0,1,2) for each slot
        // state is an integer where each slot's count is a digit in base 3
        // max state = 3^numSlots - 1
        int maxState = (int)Math.pow(3, numSlots);
        int[] dp = new int[maxState];
        for (int i = 0; i < maxState; i++) dp[i] = -1;
        dp[0] = 0;

        for (int num : nums) {
            int[] newDp = new int[maxState];
            for (int i = 0; i < maxState; i++) newDp[i] = -1;

            for (int state = 0; state < maxState; state++) {
                if (dp[state] == -1) continue;

                // Try to put current num into any slot that has less than 2 numbers
                int curVal = dp[state];
                for (int slot = 0; slot < numSlots; slot++) {
                    int count = (state / (int)Math.pow(3, slot)) % 3;
                    if (count < 2) {
                        int newState = state + (int)Math.pow(3, slot);
                        int andVal = num & (slot + 1);
                        newDp[newState] = Math.max(newDp[newState], curVal + andVal);
                    }
                }
            }
            dp = newDp;
        }

        int ans = 0;
        for (int val : dp) {
            if (val > ans) ans = val;
        }
        return ans;
    }
}

